import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public interface Part {}

    public static final class Value {
        private final boolean template;
        private final String expression;

        public Value(boolean template, String expression) {
            if (expression == null) throw new IllegalArgumentException("null expression");
            this.template = template;
            this.expression = expression;
        }
    }

    public static final class TemplateField implements Part {
        private final List<Value> values;

        public TemplateField(List<Value> values) {
            if (values == null || values.contains(null)) {
                throw new IllegalArgumentException("invalid values");
            }
            this.values = Collections.unmodifiableList(new ArrayList<>(values));
        }
    }

    public static final class FixedText implements Part {
        private final String text;

        public FixedText(String text) {
            if (text == null) throw new IllegalArgumentException("null text");
            this.text = text;
        }
    }

    public static boolean canExpand(List<? extends Part> parts) {
        if (parts == null) return false;
        for (Part part : parts) {
            if (!(part instanceof TemplateField)) return false;
            TemplateField field = (TemplateField) part;
            for (Value value : field.values) {
                if (!value.template || !value.expression.isEmpty()) return false;
            }
        }
        return true;
    }
}
